<template>
  <section class="qga-page" aria-label="创意作品广场">
    <header class="qga-hero">
      <div class="qga-hero-copy"><span class="qga-eyebrow"><i></i>QGAUSS / THE IDEA EXCHANGE</span><h1>想象力，<br><mark>在这里碰头。</mark><sup>✳</sup></h1><p>让好画面带你去一个没想过的地方。<br>看见、收藏，再长出自己的新灵感。</p><div class="qga-hero-actions"><a class="qga-primary" href="/painting" @click.prevent="router.push('/painting')">把想法变成作品<ClientIcon name="arrowUpRight" /></a><button class="qga-text" type="button" @click="showFavorites(true)">先逛逛我的收藏 <span>↘</span></button></div></div>
      <div class="qga-hero-art" aria-hidden="true"><div class="qga-orbit"></div><span class="qga-hero-star">✦</span><div class="qga-glass-frame qga-frame-back"><span>MAKE ROOM<br>FOR THE UNEXPECTED.</span><i>Q</i></div><div class="qga-glass-frame qga-frame-front"><div class="qga-sculpture"><i></i><i></i><i></i><b>✳</b></div><small>AN OPEN SPACE FOR GOOD IDEAS</small><strong>一点新鲜，<br>很多可能。</strong><span>QGAUSS GALLERY <i>↗</i></span></div><div class="qga-floating-tag"><span>✧</span> GOOD THINGS START HERE</div></div>
    </header>
    <section ref="collection" class="qga-collection" aria-labelledby="qga-collection-title">
      <div class="qga-collection-heading"><div><span class="qga-eyebrow">FIND YOUR NEXT LITTLE IDEA</span><h2 id="qga-collection-title">{{ favorites ? '喜欢的，留在这里。' : '下一点灵感，往下找。' }}</h2></div><div class="qga-collection-actions"><button type="button" class="qga-saved" :aria-pressed="favorites" @click="showFavorites"><ClientIcon name="heart" />{{ favorites?'回到全部作品':'我的收藏' }}<b v-if="Number.isInteger(counts.favorites)">{{ counts.favorites }}</b></button><button type="button" class="qga-refresh" aria-label="刷新作品广场" :disabled="loading||writing" @click="refresh"><ClientIcon name="refresh" /></button></div></div>
      <form class="qga-search" role="search" @submit.prevent="search"><ClientIcon name="search" /><input v-model="query" type="search" maxlength="100" aria-label="搜索公开作品" placeholder="搜一搜画面、风格，或一个突然冒出的想法…"/><button type="submit">找点灵感 <span>↗</span></button></form>
      <div class="qga-filter-bar"><div class="qga-kinds" aria-label="作品类型"><button v-for="type in kinds" :key="type.id" type="button" :aria-pressed="kind===type.id" @click="filter('kind',type.id)">{{ type.title }}<span v-if="Number.isInteger(counts[type.id])">{{ counts[type.id] }}</span></button></div><label class="qga-sort"><ClientIcon name="layout"/><select v-model="sort" aria-label="作品排序" @change="filter('sort',sort)"><option v-if="favorites" value="saved">最近收藏</option><option value="featured">推荐先看</option><option value="newest">最新发布</option></select></label></div>
      <div v-if="categories.length" class="qga-categories" aria-label="作品分类"><button type="button" :aria-pressed="!category" @click="filter('category','')">所有风格</button><button v-for="cat in categories" :key="cat.id" type="button" :aria-pressed="category===cat.id" @click="filter('category',cat.id)">{{ cat.name }}</button></div>
      <div v-if="pendingFavorite" class="qga-recovery" role="status"><ClientIcon name="heart"/><p>{{ pendingChecked?'原作品仍可读取，请确认是否继续这次收藏设置。':'上一次收藏结果还未核对。先找回原作品，不会自动重发。' }}</p><button v-if="!pendingChecked" type="button" :disabled="writing" @click="checkFavorite">{{ writing?'正在核对…':'核对原结果' }}</button><template v-else><button type="button" :disabled="writing" @click="saveFavorite(pendingFavorite)">继续这次设置</button><button type="button" :disabled="writing" @click="remember(null)">结束等待</button></template></div>
      <p v-if="notice" class="qga-notice" role="status">{{ notice }}</p>
      <div v-if="loadError" class="qga-empty qga-error" role="alert"><span>↻</span><h3>灵感暂时还没抵达。</h3><p>{{ loadError }}</p><button type="button" class="qga-primary" @click="refresh">重新加载</button></div>
      <div v-else-if="loading&&!items.length" class="qga-masonry qga-skeletons" role="status" aria-label="正在加载公开作品"><div v-for="n in 6" :key="n" class="qga-skeleton"><QLoader :size="24"/><span>正在为好想法留位置…</span></div></div>
      <template v-else-if="items.length"><div class="qga-result-note"><span>{{ total }} 份{{ favorites?'已收藏的公开':'公开' }}灵感 <i>·</i> 第 {{ page }} 页</span><span v-if="loading"><QLoader :size="14"/>正在同步作品…</span><span v-else>只展示作者主动公开的作品</span></div><div class="qga-masonry" :aria-busy="loading"><article v-for="(work,index) in items" :key="work.key" class="qga-card" :style="{'--qga-tile':index%4}"><button type="button" class="qga-card-open" :aria-label="'查看公开作品：'+work.title" @click="open(work,$event)"><div class="qga-card-image" :style="{aspectRatio:ratio(work.ratio)}"><img v-if="cover(work)&&assets.urls.has(cover(work))" :src="assets.urls.get(cover(work))" :alt="work.title" loading="lazy" @error="imageFailed(work.assets[0],$event)"/><div v-else class="qga-image-placeholder"><span>✳</span><small>{{ cover(work)&&assets.errors.has(cover(work))?'打开作品，重新看看':'画面正在显影…' }}</small></div><span v-if="work.featured" class="qga-featured">✦ 值得一看</span><span v-if="work.assets[0]?.kind==='video'" class="qga-motion-label"><ClientIcon name="play"/>动态作品</span><span class="qga-open-corner"><ClientIcon name="arrowUpRight"/></span><span v-if="work.assetCount>1" class="qga-asset-count">{{ work.assetCount }} 个画面</span></div><div class="qga-card-copy"><span class="qga-card-kind">{{ kindName(work.kind) }} <i>·</i> {{ work.modelLabel }}</span><h3>{{ work.title }}</h3><div class="qga-card-author"><span>{{ initials(work.author) }}</span><b>{{ work.author }}</b><small>{{ date(work.publishedAt||work.createdAt) }}</small></div></div></button><button type="button" class="qga-card-heart" :aria-label="(work.favorite?'取消收藏作品：':'收藏作品：')+work.title" :aria-pressed="work.favorite" :disabled="writing||!!pendingFavorite" @click="toggleFavorite(work)"><ClientIcon name="heart"/><span>{{ work.favoriteCount }}</span></button></article></div><nav class="qga-pagination" aria-label="公开作品分页"><button type="button" :disabled="page===1||loading" @click="turn(-1)">← 上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/pageSize)) }}</span><button type="button" :disabled="page*pageSize>=total||loading" @click="turn(1)">再遇见一些 →</button></nav></template>
      <div v-else class="qga-empty"><span>✳</span><h3>{{ committedQuery||category?'换个方向，灵感还在。':favorites?'给喜欢的作品，留一个位置。':'第一份公开灵感，等你带来。' }}</h3><p>{{ committedQuery||category?'暂时没有符合条件的公开作品，试试其他关键词或风格。':favorites?'遇到喜欢的作品，点一下爱心，下次就能在这里再相遇。':'在创作工作台完成作品后，主动选择公开，它就有机会在这里被遇见。' }}</p><button v-if="committedQuery||category||favorites" class="qga-primary" type="button" @click="clearFilters">看看全部作品<ClientIcon name="arrowUpRight"/></button><a v-else class="qga-primary" href="/painting" @click.prevent="router.push('/painting')">去做第一份创作<ClientIcon name="arrowUpRight"/></a></div>
    </section>
    <footer class="qga-footer"><span>QGAUSS / IMAGINATION HAS COMPANY</span><p>从别人的好想法里，找到属于你的下一步。</p><i>✧</i></footer>
    <dialog ref="dialog" class="qga-dialog" aria-labelledby="qga-detail-title" @cancel.prevent="close" @close="stopPlayer">
      <header><span class="qga-eyebrow">A GOOD IDEA, UP CLOSE</span><button type="button" class="qga-close" aria-label="关闭作品详情" @click="close">×</button></header>
      <div v-if="detailLoading&&!selected" class="qga-detail-wait" role="status"><QLoader :size="36"/><h2 id="qga-detail-title">正在打开这份灵感…</h2></div>
      <div v-else-if="detailError" class="qga-empty qga-error" role="alert"><span>↗</span><h2 id="qga-detail-title">这份作品暂时无法打开。</h2><p>{{ detailError }}</p><button v-if="decodeKey(detailKey)" class="qga-primary" type="button" @click="retryDetail">重新核对</button><button v-else class="qga-primary" type="button" @click="close">回到作品广场</button></div>
      <div v-else-if="selected" class="qga-detail-layout">
        <div class="qga-detail-stage"><div class="qga-detail-media"><video v-if="videoUrl&&currentAsset?.kind==='video'" ref="player" :src="videoUrl" :poster="assetSource(currentAsset)" controls playsinline preload="metadata" @error="onVideoError"/><img v-else-if="assetSource(currentAsset)" :src="assetSource(currentAsset)" :alt="selected.title+'，第 '+(assetIndex+1)+' 个画面'" @error="imageFailed(currentAsset,$event)"/><div v-else class="qga-image-placeholder"><QLoader v-if="currentAsset?.url&&!assets.errors.has(currentAsset.url)" :size="32"/><span v-else>✳</span><p>{{ currentAsset?.url&&assets.errors.get(currentAsset.url)||'这份作品暂时没有可读取的画面。' }}</p><button v-if="currentAsset?.url" type="button" @click="assets.load(currentAsset,true)">重新加载画面</button></div><button v-if="currentAsset?.kind==='video'&&!videoUrl" class="qga-play" type="button" :disabled="mediaLoading" aria-label="播放公开作品" @click="play"><QLoader v-if="mediaLoading" :size="24"/><ClientIcon v-else name="play"/></button></div><div class="qga-carousel"><button type="button" aria-label="上一个作品画面" :disabled="assetIndex===0" @click="selectAsset(-1)">←</button><span>{{ assetIndex+1 }} / {{ selected.assets.length }} <small>把这一刻，多看一眼</small></span><button type="button" aria-label="下一个作品画面" :disabled="assetIndex>=selected.assets.length-1" @click="selectAsset(1)">→</button></div><p v-if="mediaError" class="qga-media-error" role="alert">{{ mediaError }}</p></div>
        <section class="qga-inspector"><span class="qga-card-kind">{{ kindName(selected.kind) }} <i>·</i> {{ selected.modelLabel }}</span><h2 id="qga-detail-title" ref="detailHeading" tabindex="-1">{{ selected.title }}</h2><div class="qga-detail-author"><span>{{ initials(selected.author) }}</span><div><b>{{ selected.author }}</b><small>{{ date(selected.publishedAt||selected.createdAt) }} {{ selected.publishedAt?'公开的作品':'创作的作品' }}</small></div><button class="qga-detail-heart" type="button" :aria-label="selected.favorite?'取消收藏当前作品':'收藏当前作品'" :aria-pressed="selected.favorite" :disabled="writing||!!pendingFavorite" @click="toggleFavorite(selected)"><ClientIcon name="heart"/>{{ selected.favoriteCount }}</button></div><div class="qga-prompt"><div><h3>画面背后的想法</h3><button type="button" :disabled="!selected.prompt" @click="copyPrompt"><ClientIcon name="copy"/>复制</button></div><p>{{ selected.prompt||'作者没有留下可复用的文字描述。' }}</p><details v-if="selected.negativePrompt"><summary>不想出现在画面里的内容</summary><p>{{ selected.negativePrompt }}</p></details></div><dl class="qga-parameters"><div v-for="(parameter,index) in selected.parameters" :key="index"><dt>{{ parameter.label }}</dt><dd>{{ parameter.value }}</dd></div></dl><div class="qga-detail-actions"><button class="qga-primary" type="button" :disabled="!selected.reuse?.available||detailLoading||writing" @click="reuse">带着灵感，去创作<ClientIcon name="arrowUpRight"/></button><p>{{ selected.reuse?.reason||'只带入公开的文字与设定；私有参考图、选区和费用不会跟随。生成仍由你确认。' }}</p><div><button type="button" :disabled="mediaLoading" @click="download"><ClientIcon name="download"/>保存{{ currentAsset?.kind==='video'?'视频':'画面' }}</button><button type="button" @click="copyLink"><ClientIcon name="copy"/>复制作品链接</button><button type="button" :disabled="detailLoading" @click="retryDetail"><ClientIcon name="refresh"/>{{ detailLoading?'核对中…':'同步公开状态' }}</button></div></div><div v-if="pendingFavorite?.key===selected.key" class="qga-recovery"><p>{{ pendingChecked?'原作品仍在，请确认是否继续这次设置。':'收藏结果还未核对，不会自动重发。' }}</p><button v-if="!pendingChecked" type="button" :disabled="writing" @click="checkFavorite">核对原结果</button><template v-else><button type="button" :disabled="writing" @click="saveFavorite(pendingFavorite)">继续这次设置</button><button type="button" :disabled="writing" @click="remember(null)">结束等待</button></template></div><p v-if="detailNotice" class="qga-notice" role="status">{{ detailNotice }}</p><GalleryCuration v-if="auth.isAdmin" :key="selected.key" :work="selected" @updated="curationUpdated" /></section>
      </div>
    </dialog>
  </section>
</template>

<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router';
import {api} from '../../api/client.js';
import {useAuth} from '../../stores/auth.js';
import {createArtworkAssets} from '../../lib/artwork-assets.js';
import ClientIcon from '../reference/ClientIcon.vue';
import QLoader from '../QLoader.vue';
import GalleryCuration from './GalleryCuration.vue';
import './creative-gallery.css';

const auth=useAuth(),route=useRoute(),router=useRouter();
const items=ref([]),categories=ref([]),counts=reactive({}),total=ref(0),page=ref(1),pageSize=18;
const kind=ref('all'),sort=ref('featured'),category=ref(''),favorites=ref(false),query=ref(''),committedQuery=ref('');
const loading=ref(false),loadError=ref(''),notice=ref(''),writing=ref(false),pendingFavorite=ref(null),pendingChecked=ref(false);
const dialog=ref(null),collection=ref(null),selected=ref(null),detailLoading=ref(false),detailError=ref(''),detailNotice=ref(''),detailHeading=ref(null),assetIndex=ref(0);
const player=ref(null),videoUrl=ref(''),mediaLoading=ref(false),mediaError=ref('');
const kinds=[{id:'all',title:'全部灵感'},{id:'image',title:'图像创作'},{id:'mj',title:'MJ 灵感'},{id:'video',title:'流动画面'}];
let alive=true,epoch=0,listRevision=0,detailRevision=0,mediaRevision=0,trigger=null,detailKey='',assets;
const reads=new Map(),stamp=()=>({id:auth.user?.id,identity:auth.identityRevision,epoch}),current=s=>alive&&auth.isLoggedIn&&s.id===auth.user?.id&&s.identity===auth.identityRevision&&s.epoch===epoch;
const active=()=>alive&&auth.isLoggedIn;
assets=createArtworkAssets(active);
const currentAsset=computed(()=>selected.value?.assets[assetIndex.value]||null);
const keyOf=work=>work.kind+':'+work.id,kindName=type=>({image:'图像创作',mj:'MJ 创作',video:'视频创作'})[type]||'公开作品';
const initials=name=>String(name||'Q').slice(0,1),ratio=value=>typeof value==='string'&&/^[1-9][0-9]?:[1-9][0-9]?$/.test(value)?value.replace(':','/'):'3/4';
const date=value=>{if(!value)return '时间待确认';const time=new Date(value);return Number.isFinite(time.getTime())?new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit'}).format(time):'时间待确认';};
const cover=work=>work.assets?.[0]?.url||'',assetSource=file=>file?.url?assets.urls.get(file.url):undefined;
function request(key){reads.get(key)?.abort();const controller=new AbortController();reads.set(key,controller);return{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(20000)]),current:()=>reads.get(key)===controller&&!controller.signal.aborted};}
function decodeKey(value){if(typeof value!=='string'||value.length>140)return null;const match=/^(image|mj|video):([A-Za-z0-9_-]{1,128})$/.exec(value);return match?{kind:match[1],id:match[2]}:null;}
function valid(work,full=false){
 if(!work||!decodeKey(keyOf(work))||work.key!==keyOf(work)||typeof work.title!=='string'||!work.title||typeof work.author!=='string'||typeof work.favorite!=='boolean'||!Number.isInteger(work.favoriteCount)||work.favoriteCount<0||!Array.isArray(work.assets)||!work.assets.length||!Number.isInteger(work.assetCount)||work.assetCount<work.assets.length)throw Error('作品资料不完整，请重新核对。');
 if(!work.assets.every((file,index)=>file.index===index&&['image','video'].includes(file.kind)&&file.url==='/api/gallery/works/'+work.kind+'/'+encodeURIComponent(work.id)+'/assets/'+index+(full?'':'?thumb=1')))throw Error('作品画面资料不完整，请重新核对。');
 if(full&&(work.assetCount!==work.assets.length||typeof work.prompt!=='string'||!Array.isArray(work.parameters)||!work.parameters.every(row=>typeof row.label==='string'&&typeof row.value==='string')||!work.reuse||typeof work.reuse.available!=='boolean'||work.reuse.path!==({image:'/painting',mj:'/mj',video:'/video'})[work.kind]))throw Error('作品设定不完整，请重新核对。');return work;
}
function retain(){const covers=items.value.flatMap(row=>row.assets),files=[...covers,...(selected.value?.assets||[])];assets.retain(new Set(files.map(file=>file.url)));for(const file of covers)void assets.load(file);if(currentAsset.value)void assets.load(currentAsset.value);}
function imageFailed(file,event){const value=file?.url&&assets.urls.get(file.url);if(active()&&value&&event.currentTarget?.currentSrc===value){URL.revokeObjectURL(value);assets.urls.delete(file.url);assets.errors.set(file.url,'画面暂时无法解码，请重新加载。');}}
function friendly(error,fallback){return error?.name==='TypeError'?'暂时无法连接，请稍后重新核对。':error?.name==='TimeoutError'?'连接等待超时，请重新核对原结果。':error?.name==='AbortError'?'连接已中断，请重新核对原结果。':error?.message||fallback;}
async function loadOptions(){if(!active())return;const s=stamp(),read=request('options');try{const value=await api.get('/gallery/options',{signal:read.signal,retry:false});if(!current(s)||!read.current())return;if(!Array.isArray(value.categories))throw Error('作品分类暂未确认。');categories.value=value.categories.filter(row=>typeof row.id==='string'&&typeof row.name==='string');for(const [key,count] of Object.entries(value.counts||{}))if(['all','image','mj','video','favorites'].includes(key)&&Number.isInteger(count)&&count>=0)counts[key]=count;}catch(error){if(current(s)&&read.current())notice.value=friendly(error,'作品分类暂未加载，可先浏览全部作品。');}}
async function load(){
 if(!active())return;const s=stamp(),revision=++listRevision,read=request('list');loading.value=true;loadError.value='';
 try{const params=new URLSearchParams({page:String(page.value),pageSize:String(pageSize),kind:kind.value,sort:sort.value});if(category.value)params.set('catId',category.value);if(committedQuery.value)params.set('q',committedQuery.value);if(favorites.value)params.set('favorites','1');const data=await api.get('/gallery/works?'+params,{signal:read.signal,retry:false});if(!current(s)||!read.current()||revision!==listRevision)return;if(!Array.isArray(data.items)||!Number.isInteger(data.total)||data.total<0)throw Error('作品列表暂未确认，请重新加载。');items.value=data.items.map(row=>valid(row));total.value=data.total;retain();if(page.value>1&&!items.value.length&&data.total>0){page.value=Math.ceil(data.total/pageSize);void load();}}
 catch(error){if(current(s)&&read.current()&&revision===listRevision){items.value=[];retain();loadError.value=friendly(error,'作品暂未加载，请重试。');}}
 finally{if(current(s)&&read.current()&&revision===listRevision)loading.value=false;}
}
function scrollCollection(){collection.value?.scrollIntoView?.({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function filter(field,value){if(field==='kind')kind.value=value;if(field==='sort')sort.value=value;if(field==='category')category.value=value;page.value=1;void load();}
function search(){committedQuery.value=query.value.trim();page.value=1;void load();}
function clearFilters(){kind.value='all';category.value=query.value=committedQuery.value='';favorites.value=false;if(sort.value==='saved')sort.value='featured';page.value=1;void load();}
function showFavorites(value){favorites.value=typeof value==='boolean'?value:!favorites.value;if(favorites.value)sort.value='saved';else if(sort.value==='saved')sort.value='featured';page.value=1;void load();scrollCollection();}
function turn(direction){page.value+=direction;void load();scrollCollection();}
async function refresh(){await Promise.all([loadOptions(),load()]);}
function stopPlayer(){mediaRevision++;reads.get('media')?.abort();if(player.value){player.value.pause();player.value.removeAttribute('src');player.value.load?.();}videoUrl.value='';mediaLoading.value=false;mediaError.value='';}
async function readDetail(key,{refresh=false}={}){
 const parsed=decodeKey(key);detailKey=typeof key==='string'?key:'';const revision=++detailRevision,s=stamp(),read=request('detail');detailError.value=detailNotice.value='';detailLoading.value=true;
 if(!refresh){stopPlayer();selected.value=null;assetIndex.value=0;retain();}await nextTick();if(current(s)&&read.current()&&!dialog.value?.open)dialog.value?.showModal();
 if(!parsed){if(current(s)&&read.current()){detailError.value='作品入口不完整，请回到广场重新选择。';detailLoading.value=false;}return;}
 try{const work=valid(await api.get('/gallery/works/'+parsed.kind+'/'+encodeURIComponent(parsed.id),{signal:read.signal,retry:false}),true);if(!current(s)||!read.current()||revision!==detailRevision)return;if(work.key!==key)throw Error('作品与入口不一致，请重新选择。');selected.value=work;if(assetIndex.value>=work.assets.length){stopPlayer();assetIndex.value=0;}retain();await nextTick();if(current(s)&&!refresh)detailHeading.value?.focus({preventScroll:true});}
 catch(error){if(current(s)&&read.current()&&revision===detailRevision){stopPlayer();selected.value=null;retain();detailError.value=error.status===404?'这份作品已撤回、被移除或当前不可用。':friendly(error,'作品暂时无法打开。');}}
 finally{if(current(s)&&read.current()&&revision===detailRevision)detailLoading.value=false;}
}
function open(work,event){trigger=event?.currentTarget||null;const key=work.key;if(route.query.work===key)void readDetail(key);else void router.push({path:'/market',query:{...route.query,work:key}});}
function close({fromRoute=false}={}){detailRevision++;reads.get('detail')?.abort();stopPlayer();selected.value=null;detailError.value=detailNotice.value='';detailLoading.value=false;dialog.value?.close();retain();if(!fromRoute&&route.query.work!==undefined){const query={...route.query};delete query.work;void router.replace({path:'/market',query});}if(trigger?.isConnected)trigger.focus({preventScroll:true});trigger=null;}
function retryDetail(){if(detailKey)void readDetail(detailKey,{refresh:true});}
function selectAsset(direction){if(!selected.value)return;stopPlayer();assetIndex.value=Math.max(0,Math.min(selected.value.assets.length-1,assetIndex.value+direction));retain();}
async function media(){const work=selected.value,file=currentAsset.value;if(!work||file?.kind!=='video')return null;const s=stamp(),revision=++mediaRevision,read=request('media');mediaLoading.value=true;mediaError.value='';try{const value=await api.get('/gallery/works/'+work.kind+'/'+encodeURIComponent(work.id)+'/playback?index='+file.index,{signal:read.signal,retry:false});if(!current(s)||!read.current()||revision!==mediaRevision||selected.value?.key!==work.key||currentAsset.value?.index!==file.index)return null;const prefix='/api/'+work.kind+'/media/'+encodeURIComponent(work.id)+(work.kind==='mj'?'/'+file.index:'/video')+'?';if(typeof value.videoUrl!=='string'||!value.videoUrl.startsWith(prefix)||!new URL(value.videoUrl,location.origin).searchParams.get('ticket'))throw Error('播放凭证不完整，请重新核对。');return value;}catch(error){if(current(s)&&read.current()&&revision===mediaRevision)mediaError.value=error.status===404?'作品已撤回或文件不可用，请同步公开状态。':friendly(error,'播放暂未连接，请重试。');return null;}finally{if(current(s)&&read.current()&&revision===mediaRevision)mediaLoading.value=false;}}
async function play(){const value=await media();if(!value)return;videoUrl.value=value.videoUrl;const s=stamp(),key=selected.value?.key;await nextTick();try{await player.value?.play();}catch{if(current(s)&&selected.value?.key===key)mediaError.value='画面已准备好，请点击播放器中的播放按钮。';}}
function onVideoError(){if(active()){stopPlayer();mediaError.value='这段画面暂时无法播放，可重新点击播放取得新凭证，或同步公开状态。';}}
function downloadFile(url,name){const link=document.createElement('a');link.href=url;link.download=name;link.rel='noopener';document.body.append(link);link.click();link.remove();}
async function download(){const work=selected.value,file=currentAsset.value;if(!work||!file||mediaLoading.value)return;const s=stamp();try{if(file.kind==='video'){const value=await media();if(value&&current(s)&&selected.value?.key===work.key)downloadFile(value.videoUrl+(value.videoUrl.includes('?')?'&':'?')+'download=1','QGauss-'+work.id+'.mp4');}else{const result=await assets.load(file);if(result?.url&&current(s)&&selected.value?.key===work.key&&currentAsset.value?.index===file.index)downloadFile(result.url,'QGauss-'+work.id+'-'+(file.index+1)+'.'+({['image/jpeg']:'jpg',['image/svg+xml']:'svg'}[result.blob.type]||result.blob.type.split('/')[1]||'png'));}}catch(error){if(current(s))mediaError.value=friendly(error,'保存暂未完成，请重试。');}}
async function copy(text,message){const s=stamp(),key=selected.value?.key;try{await navigator.clipboard.writeText(text);if(current(s)&&selected.value?.key===key)detailNotice.value=message;}catch{if(current(s)&&selected.value?.key===key)detailNotice.value='暂时无法访问剪贴板，请选中文字手动复制。';}}
function copyPrompt(){if(selected.value?.prompt)void copy(selected.value.prompt,'这份画面描述已复制，可以继续写成自己的想法。');}
function copyLink(){if(selected.value)void copy(new URL('/market?work='+encodeURIComponent(selected.value.key),location.origin).href,'作品链接已复制。站内登录后可查看仍处于公开状态的作品。');}
function reuse(){const work=selected.value;if(!work?.reuse?.available||detailLoading.value)return;stopPlayer();void router.push({path:work.reuse.path,query:{gallery:work.key}});}
function curationUpdated(value){for(const work of items.value)if(work.key===value.key)work.featured=value.featured;if(selected.value?.key===value.key)selected.value.featured=value.featured;void load();}
function remember(value){pendingFavorite.value=value;pendingChecked.value=false;try{value?sessionStorage.setItem('qg:gallery-favorite:'+auth.user?.id,JSON.stringify(value)):sessionStorage.removeItem('qg:gallery-favorite:'+auth.user?.id);}catch{notice.value='收藏结果的临时记录未能保存，请在本页核对后再离开。';}}
function patchFavorite(work){for(const row of items.value)if(row.key===work.key){row.favorite=work.favorite;row.favoriteCount=work.favoriteCount;}if(selected.value?.key===work.key){selected.value.favorite=work.favorite;selected.value.favoriteCount=work.favoriteCount;}}
function toggleFavorite(work){if(!writing.value&&!pendingFavorite.value)void saveFavorite({key:work.key,favorite:!work.favorite});}
async function saveFavorite(intent){const parsed=decodeKey(intent?.key);if(!parsed||typeof intent.favorite!=='boolean'||writing.value)return;const s=stamp(),read=request('favorite');remember(intent);writing.value=true;notice.value='';try{const value=await api.put('/gallery/works/'+parsed.kind+'/'+encodeURIComponent(parsed.id)+'/favorite',{favorite:intent.favorite},{signal:read.signal,retry:false});if(!current(s))return;if(value.key!==intent.key||value.favorite!==intent.favorite||!Number.isInteger(value.favoriteCount)||value.favoriteCount<0)throw Error('收藏回执尚未确认，请先核对原作品。');patchFavorite(value);remember(null);notice.value=intent.favorite?'喜欢的作品，已经为你留好。':'已取消收藏，作品仍可在公开广场浏览。';if(selected.value?.key===intent.key)detailNotice.value=notice.value;await refresh();}catch(error){if(current(s)){if(error.status>=400&&error.status<500&&![408,429].includes(error.status))remember(null);notice.value=friendly(error,'收藏结果尚未确认，请先核对原作品。');if(selected.value?.key===intent.key)detailNotice.value=notice.value;}}finally{if(current(s))writing.value=false;}}
async function checkFavorite(){const intent=pendingFavorite.value,parsed=decodeKey(intent?.key);if(!parsed||writing.value)return;const s=stamp(),read=request('favorite-recovery');writing.value=true;try{const work=valid(await api.get('/gallery/works/'+parsed.kind+'/'+encodeURIComponent(parsed.id),{signal:read.signal,retry:false}),true);if(!current(s)||pendingFavorite.value?.key!==intent.key)return;patchFavorite(work);if(work.favorite===intent.favorite){remember(null);notice.value='已找回原收藏结果，没有重复执行。';await refresh();}else{pendingChecked.value=true;notice.value='原作品仍在，请明确选择是否继续这次设置。';}}catch(error){if(current(s)){if(error.status===404){remember(null);notice.value='原作品已撤回或不可用，没有重新提交收藏。';await refresh();}else notice.value=friendly(error,'暂未核对到收藏结果。');}}finally{if(current(s))writing.value=false;}}
async function bootstrap(){if(!active())return;try{const value=JSON.parse(sessionStorage.getItem('qg:gallery-favorite:'+auth.user?.id)||'null');if(value&&decodeKey(value.key)&&typeof value.favorite==='boolean')pendingFavorite.value={key:value.key,favorite:value.favorite};}catch{/* In-memory recovery remains available. */}const entry=route.query.work;await Promise.allSettled([refresh(),entry!==undefined?readDetail(entry):Promise.resolve()]);}
function beforeUnload(event){if(writing.value){event.preventDefault();event.returnValue='';}}
onBeforeRouteLeave(()=>!writing.value);
watch(()=>route.query.work,(value,prior)=>{if(value===prior||!active())return;if(value===undefined)close({fromRoute:true});else void readDetail(value);});
watch([()=>auth.user?.id,()=>auth.identityRevision],()=>{epoch++;listRevision++;detailRevision++;for(const read of reads.values())read.abort();reads.clear();stopPlayer();dialog.value?.close();assets.close();assets=createArtworkAssets(active);items.value=[];selected.value=null;categories.value=[];for(const key of Object.keys(counts))delete counts[key];total.value=0;pendingFavorite.value=null;pendingChecked.value=writing.value=loading.value=detailLoading.value=false;notice.value=loadError.value=detailError.value=detailNotice.value='';detailKey='';kind.value='all';favorites.value=false;category.value=query.value=committedQuery.value='';page.value=1;if(active())void bootstrap();});
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);void bootstrap();});
onBeforeUnmount(()=>{alive=false;epoch++;for(const read of reads.values())read.abort();stopPlayer();assets.close();dialog.value?.close();window.removeEventListener('beforeunload',beforeUnload);});
</script>
